// solde du debut de la journee, depots et retraits du jour compris : solde actuel moins le resultat des transactions du jour
double DayBaseline(const datetime day, const double bal)
  {
   if(!HistorySelect(day, TimeTradeServer() + 86400)) return bal;
   double pnl = 0.0;
   int total = HistoryDealsTotal();
   for(int i = 0; i < total; i++)
     {
      ulong d = HistoryDealGetTicket(i);
      if(d == 0) continue;
      long type = HistoryDealGetInteger(d, DEAL_TYPE);
      if(type != DEAL_TYPE_BUY && type != DEAL_TYPE_SELL) continue;      // depots, retraits, corrections : pas une perte de trading
      pnl += HistoryDealGetDouble(d, DEAL_PROFIT) + HistoryDealGetDouble(d, DEAL_SWAP) + HistoryDealGetDouble(d, DEAL_COMMISSION)
             + HistoryDealGetDouble(d, DEAL_FEE);
     }
   return bal - pnl;
  }

